/**
 * Socials thumbnail creator: reference images (a person like Mia, a look to copy, assets), saved
 * styles, and covers generated by the image model in the picked format (Reel 9:16 by default).
 *
 * Same layering as studioRoutes.ts: everything with I/O comes in through ThumbnailDeps
 * (server/routes/socialThumbnails.ts wires the real ones), so the routes are tested over HTTP without
 * a database or an image model. Auth: requireAuth, then the account gate (gate.ts). Any user of the
 * account sees the gallery; making, changing and deleting is agency or a Manager (canManageSocial).
 *
 * Generating takes a minute: POST /thumbnails answers 202 at once with rows in "generating", the job
 * runs in the background and fills them; the page polls the list while any row is generating.
 */
import { randomUUID } from "node:crypto";
import { extname, resolve, sep } from "node:path";
import type { Express, RequestHandler, Response } from "express";
import type {
  InsertSocialThumbnail,
  InsertSocialThumbnailRef,
  InsertSocialThumbnailStyle,
  SocialPost,
  SocialScript,
  SocialSettings,
  SocialThumbnail,
  SocialThumbnailRef,
  SocialThumbnailStyle,
} from "@shared/schema";
import { THUMB_LIMITS, isRefKind } from "@shared/socialThumbnails";
import { wrapAsync } from "../routes/_helpers";
import { canManageSocial, isAgency } from "./access";
import { actorIdOf, forbidden, makeAccountGate, positiveIntParam, refused, type GetAccount } from "./gate";
import { createRateLimiter, type RateLimiter } from "./rateLimit";
import { visibleToClient } from "./scripts";
import { buildThumbnailPrompt, generationPlan, type GenerationPlan } from "./thumbnailPrompt";
import { decodeDataUrl, sniffImage, type ImageProvider } from "./thumbnailImage";
import {
  parseGenerateBody,
  parseRefBody,
  parseStyleBody,
  pickRequestRefs,
  toRefView,
  toStyleView,
  toThumbnailView,
} from "./thumbnails";

export interface ThumbnailDeps {
  requireAuth: RequestHandler;
  now(): Date;
  /** uploads/social-thumbnails in production: <dir>/<accountId>/<uuid>.jpg and <dir>/<accountId>/refs/<uuid>.<ext>. */
  dir: string;
  store: {
    getAccount: GetAccount;
    getSocialSettings(accountId: number): Promise<SocialSettings | null>;
    getSocialScript(accountId: number, scriptId: number): Promise<SocialScript | null>;
    getSocialPost(accountId: number, postId: number): Promise<SocialPost | null>;
    listThumbnailRefs(accountId: number): Promise<SocialThumbnailRef[]>;
    getThumbnailRef(accountId: number, refId: number): Promise<SocialThumbnailRef | null>;
    insertThumbnailRef(row: InsertSocialThumbnailRef): Promise<SocialThumbnailRef>;
    deleteThumbnailRef(accountId: number, refId: number): Promise<SocialThumbnailRef | null>;
    listThumbnailStyles(accountId: number): Promise<SocialThumbnailStyle[]>;
    insertThumbnailStyle(row: InsertSocialThumbnailStyle): Promise<SocialThumbnailStyle>;
    updateThumbnailStyle(accountId: number, styleId: number, fields: Partial<InsertSocialThumbnailStyle>): Promise<SocialThumbnailStyle | null>;
    deleteThumbnailStyle(accountId: number, styleId: number): Promise<boolean>;
    listThumbnails(accountId: number): Promise<SocialThumbnail[]>;
    getThumbnail(accountId: number, thumbId: number): Promise<SocialThumbnail | null>;
    insertThumbnails(rows: InsertSocialThumbnail[]): Promise<SocialThumbnail[]>;
    updateThumbnails(ids: number[], fields: Partial<InsertSocialThumbnail>): Promise<void>;
    setThumbnailStarred(accountId: number, thumbId: number, starred: boolean): Promise<SocialThumbnail | null>;
    deleteThumbnail(accountId: number, thumbId: number): Promise<SocialThumbnail | null>;
  };
  /** null when no image model is configured (OPENAI_API_KEY not set). */
  images(): ImageProvider | null;
  files: {
    read(path: string): Promise<Buffer>;
    write(path: string, data: Buffer): Promise<void>;
    /** A missing file is fine. */
    remove(path: string): Promise<void>;
    /** thumbnailImage.writeThumbnailJpeg: crop and scale the model's image to the format. */
    writeJpeg(image: Buffer, plan: GenerationPlan, destPath: string): Promise<void>;
  };
}

/** 15 generate requests per user per 10 minutes (each makes up to 3 images). */
export function thumbnailLimiter(): RateLimiter {
  return createRateLimiter({ max: 15, windowMs: 10 * 60_000 });
}

/** An account runs at most this many generate requests at once. */
const MAX_RUNNING_PER_ACCOUNT = 3;

const MIME_BY_EXT: Record<string, string> = { ".jpg": "image/jpeg", ".png": "image/png", ".webp": "image/webp" };

export function registerThumbnailRoutes(app: Express, deps: ThumbnailDeps, limiter: RateLimiter = thumbnailLimiter()): { idle(): Promise<void> } {
  const { store, files } = deps;
  const accountGate = makeAccountGate((id) => store.getAccount(id));
  const root = resolve(deps.dir);
  const inside = (path: string | null): path is string => !!path && resolve(path).startsWith(root + sep);
  const running = new Map<number, number>();
  const jobs = new Set<Promise<void>>();

  const sendImage = (res: Response, path: string, downloadName: string | null) => {
    const type = MIME_BY_EXT[extname(path).toLowerCase()] ?? "application/octet-stream";
    const headers: Record<string, string> = { "Content-Type": type, "Cache-Control": "private, max-age=86400" };
    if (downloadName) headers["Content-Disposition"] = `attachment; filename="${downloadName}"`;
    res.sendFile(resolve(path), { headers }, (err) => {
      if (err && !res.headersSent) res.status((err as { status?: number }).status ?? 404).end();
    });
  };

  const removeQuietly = async (path: string | null) => {
    if (!inside(path)) return;
    try {
      await files.remove(path);
    } catch (err: any) {
      console.error(`[thumbnails] could not delete ${path}: ${err?.message ?? err}`);
    }
  };

  // ─── Config: is an image model switched on ────────────────────────────────
  app.get("/api/social/accounts/:id/thumbnails/config", deps.requireAuth, wrapAsync(async (req, res) => {
    const ctx = await accountGate(req, res);
    if (!ctx) return;
    res.json({ configured: deps.images() !== null, canCreate: canManageSocial(req.user, ctx.accountId) });
  }));

  // ─── Reference images ─────────────────────────────────────────────────────
  app.get("/api/social/accounts/:id/thumbnail-refs", deps.requireAuth, wrapAsync(async (req, res) => {
    const ctx = await accountGate(req, res);
    if (!ctx) return;
    res.json((await store.listThumbnailRefs(ctx.accountId)).map(toRefView));
  }));

  app.post("/api/social/accounts/:id/thumbnail-refs", deps.requireAuth, wrapAsync(async (req, res) => {
    const ctx = await accountGate(req, res);
    if (!ctx) return;
    if (!canManageSocial(req.user, ctx.accountId)) return forbidden(res);
    const userId = actorIdOf(req, res);
    if (userId === null) return;
    const parsed = parseRefBody(req.body);
    if (!parsed.ok) return res.status(400).json({ message: parsed.message });
    const data = decodeDataUrl(parsed.value.data);
    if (!data) return refused(res, 400, "bad_image");
    if (data.length > THUMB_LIMITS.refBytes) return refused(res, 413, "too_large");
    const type = sniffImage(data);
    if (!type) return refused(res, 415, "bad_image");
    if ((await store.listThumbnailRefs(ctx.accountId)).length >= THUMB_LIMITS.refsPerAccount) return refused(res, 409, "too_many");
    const filePath = resolve(root, String(ctx.accountId), "refs", `${randomUUID()}.${type.ext}`);
    await files.write(filePath, data);
    try {
      const row = await store.insertThumbnailRef({
        accountsId: ctx.accountId, kind: parsed.value.kind, label: parsed.value.label, filePath, mimeType: type.mimeType, createdByUserId: userId,
      });
      res.status(201).json(toRefView(row));
    } catch (err) {
      await removeQuietly(filePath);
      throw err;
    }
  }));

  app.get("/api/social/accounts/:id/thumbnail-refs/:refId/image", deps.requireAuth, wrapAsync(async (req, res) => {
    const ctx = await accountGate(req, res);
    if (!ctx) return;
    const refId = positiveIntParam(req, res, "refId");
    if (refId === null) return;
    const ref = await store.getThumbnailRef(ctx.accountId, refId);
    if (!ref || !inside(ref.filePath)) return res.status(404).json({ message: "Not found" });
    sendImage(res, ref.filePath, null);
  }));

  app.delete("/api/social/accounts/:id/thumbnail-refs/:refId", deps.requireAuth, wrapAsync(async (req, res) => {
    const ctx = await accountGate(req, res);
    if (!ctx) return;
    if (!canManageSocial(req.user, ctx.accountId)) return forbidden(res);
    const refId = positiveIntParam(req, res, "refId");
    if (refId === null) return;
    const ref = await store.deleteThumbnailRef(ctx.accountId, refId);
    if (!ref) return res.status(404).json({ message: "Not found" });
    await removeQuietly(ref.filePath);
    res.json({ ok: true });
  }));

  // ─── Styles ───────────────────────────────────────────────────────────────
  const refIdSet = async (accountId: number) => new Set((await store.listThumbnailRefs(accountId)).map((r) => r.id));

  app.get("/api/social/accounts/:id/thumbnail-styles", deps.requireAuth, wrapAsync(async (req, res) => {
    const ctx = await accountGate(req, res);
    if (!ctx) return;
    const ids = await refIdSet(ctx.accountId);
    res.json((await store.listThumbnailStyles(ctx.accountId)).map((s) => toStyleView(s, ids)));
  }));

  app.post("/api/social/accounts/:id/thumbnail-styles", deps.requireAuth, wrapAsync(async (req, res) => {
    const ctx = await accountGate(req, res);
    if (!ctx) return;
    if (!canManageSocial(req.user, ctx.accountId)) return forbidden(res);
    const userId = actorIdOf(req, res);
    if (userId === null) return;
    const parsed = parseStyleBody(req.body);
    if (!parsed.ok) return res.status(400).json({ message: parsed.message });
    if ((await store.listThumbnailStyles(ctx.accountId)).length >= THUMB_LIMITS.stylesPerAccount) return refused(res, 409, "too_many");
    const ids = await refIdSet(ctx.accountId);
    if (!parsed.value.refIds.every((id) => ids.has(id))) return refused(res, 422, "ref_missing");
    const row = await store.insertThumbnailStyle({ accountsId: ctx.accountId, ...parsed.value, createdByUserId: userId });
    res.status(201).json(toStyleView(row, ids));
  }));

  app.put("/api/social/accounts/:id/thumbnail-styles/:styleId", deps.requireAuth, wrapAsync(async (req, res) => {
    const ctx = await accountGate(req, res);
    if (!ctx) return;
    if (!canManageSocial(req.user, ctx.accountId)) return forbidden(res);
    const styleId = positiveIntParam(req, res, "styleId");
    if (styleId === null) return;
    const parsed = parseStyleBody(req.body);
    if (!parsed.ok) return res.status(400).json({ message: parsed.message });
    const ids = await refIdSet(ctx.accountId);
    if (!parsed.value.refIds.every((id) => ids.has(id))) return refused(res, 422, "ref_missing");
    const row = await store.updateThumbnailStyle(ctx.accountId, styleId, parsed.value);
    if (!row) return res.status(404).json({ message: "Not found" });
    res.json(toStyleView(row, ids));
  }));

  app.delete("/api/social/accounts/:id/thumbnail-styles/:styleId", deps.requireAuth, wrapAsync(async (req, res) => {
    const ctx = await accountGate(req, res);
    if (!ctx) return;
    if (!canManageSocial(req.user, ctx.accountId)) return forbidden(res);
    const styleId = positiveIntParam(req, res, "styleId");
    if (styleId === null) return;
    if (!(await store.deleteThumbnailStyle(ctx.accountId, styleId))) return res.status(404).json({ message: "Not found" });
    res.json({ ok: true });
  }));

  // ─── Thumbnails ───────────────────────────────────────────────────────────
  app.get("/api/social/accounts/:id/thumbnails", deps.requireAuth, wrapAsync(async (req, res) => {
    const ctx = await accountGate(req, res);
    if (!ctx) return;
    const now = deps.now();
    res.json((await store.listThumbnails(ctx.accountId)).map((r) => toThumbnailView(r, now)));
  }));

  app.post("/api/social/accounts/:id/thumbnails", deps.requireAuth, wrapAsync(async (req, res) => {
    const ctx = await accountGate(req, res);
    if (!ctx) return;
    if (!canManageSocial(req.user, ctx.accountId)) return forbidden(res);
    const userId = actorIdOf(req, res);
    if (userId === null) return;
    const parsed = parseGenerateBody(req.body);
    if (!parsed.ok) return res.status(400).json({ message: parsed.message });
    const input = parsed.value;
    const provider = deps.images();
    if (!provider) return refused(res, 501, "not_configured");

    // What the thumbnail is for: a script (a client user only reaches the ones sent to them) or a post.
    let context = "";
    let title = input.title;
    if (input.scriptId) {
      const script = await store.getSocialScript(ctx.accountId, input.scriptId);
      if (!script || (!isAgency(req.user) && !visibleToClient(script))) return refused(res, 404, "script_missing");
      context = script.body;
      if (!title) title = script.title.slice(0, THUMB_LIMITS.title);
    } else if (input.postId) {
      const post = await store.getSocialPost(ctx.accountId, input.postId);
      if (!post) return refused(res, 404, "post_missing");
      context = post.caption;
    }
    if (input.kind === "title" && !title) return refused(res, 422, "no_title");

    const allRefs = await store.listThumbnailRefs(ctx.accountId);
    const byId = new Map(allRefs.map((r) => [r.id, r]));
    if (!input.refIds.every((id) => byId.has(id))) return refused(res, 422, "ref_missing");
    const refs = pickRequestRefs(input.kind, input.refIds.map((id) => byId.get(id)!), allRefs);
    if (input.kind === "presenter" && !refs.some((r) => r.kind === "person")) return refused(res, 422, "no_person");

    if ((running.get(ctx.accountId) ?? 0) >= MAX_RUNNING_PER_ACCOUNT) return refused(res, 429, "busy");
    if (!limiter.take(`thumb:${userId}`, deps.now().getTime())) {
      res.setHeader("Retry-After", String(limiter.retryAfterS(`thumb:${userId}`, deps.now().getTime())));
      return refused(res, 429, "rate_limited");
    }

    const settings = await store.getSocialSettings(ctx.accountId);
    const fullPrompt = buildThumbnailPrompt({
      kind: input.kind,
      format: input.format,
      title,
      extra: input.prompt,
      context,
      about: settings?.aboutMe ?? "",
      refs: refs.map((r) => ({ kind: isRefKind(r.kind) ? r.kind : "asset", label: r.label })),
    });
    const batchId = randomUUID();
    const rows = await store.insertThumbnails(Array.from({ length: input.variants }, () => ({
      accountsId: ctx.accountId,
      batchId,
      styleId: input.styleId,
      scriptId: input.scriptId,
      postId: input.postId,
      kind: input.kind,
      format: input.format,
      title,
      prompt: input.prompt,
      fullPrompt,
      refIds: refs.map((r) => r.id),
      status: "generating",
      createdByUserId: userId,
    })));

    running.set(ctx.accountId, (running.get(ctx.accountId) ?? 0) + 1);
    const job = generate(provider, ctx.accountId, rows, generationPlan(input.format), fullPrompt, refs).finally(() => {
      const left = (running.get(ctx.accountId) ?? 1) - 1;
      if (left > 0) running.set(ctx.accountId, left);
      else running.delete(ctx.accountId);
      jobs.delete(job);
    });
    jobs.add(job);
    const now = deps.now();
    res.status(202).json(rows.map((r) => toThumbnailView(r, now)));
  }));

  /** Never throws: every row ends ready or failed. */
  async function generate(provider: ImageProvider, accountId: number, rows: SocialThumbnail[], plan: GenerationPlan, prompt: string, refs: SocialThumbnailRef[]): Promise<void> {
    const ids = rows.map((r) => r.id);
    try {
      const references = await Promise.all(refs.map(async (r) => ({
        data: await files.read(r.filePath),
        mimeType: r.mimeType,
        name: `reference-${r.id}${extname(r.filePath) || ".png"}`,
      })));
      const { images, model } = await provider.generate({ prompt, size: plan.size, n: rows.length, references });
      for (const [i, row] of rows.entries()) {
        const image = images[i];
        if (!image) {
          await store.updateThumbnails([row.id], { status: "failed", error: "no_image", model });
          continue;
        }
        const filePath = resolve(root, String(accountId), `${randomUUID()}.jpg`);
        try {
          await files.writeJpeg(image, plan, filePath);
          await store.updateThumbnails([row.id], { status: "ready", filePath, model, error: null });
        } catch (err: any) {
          console.error(`[thumbnails] could not save thumbnail ${row.id}: ${err?.message ?? err}`);
          await removeQuietly(filePath);
          await store.updateThumbnails([row.id], { status: "failed", error: "save_failed", model });
        }
      }
    } catch (err: any) {
      const message = String(err?.message ?? "failed").slice(0, 300);
      console.error(`[thumbnails] generation failed for account ${accountId}: ${message}`);
      try {
        await store.updateThumbnails(ids, { status: "failed", error: message });
      } catch (e: any) {
        console.error(`[thumbnails] could not mark ${ids.join(",")} failed: ${e?.message ?? e}`);
      }
    }
  }

  app.get("/api/social/accounts/:id/thumbnails/:thumbId/image", deps.requireAuth, wrapAsync(async (req, res) => {
    const ctx = await accountGate(req, res);
    if (!ctx) return;
    const thumbId = positiveIntParam(req, res, "thumbId");
    if (thumbId === null) return;
    const row = await store.getThumbnail(ctx.accountId, thumbId);
    if (!row || row.status !== "ready" || !inside(row.filePath)) return res.status(404).json({ message: "Not found" });
    sendImage(res, row.filePath, req.query.download ? `thumbnail-${row.id}.jpg` : null);
  }));

  app.patch("/api/social/accounts/:id/thumbnails/:thumbId", deps.requireAuth, wrapAsync(async (req, res) => {
    const ctx = await accountGate(req, res);
    if (!ctx) return;
    if (!canManageSocial(req.user, ctx.accountId)) return forbidden(res);
    const thumbId = positiveIntParam(req, res, "thumbId");
    if (thumbId === null) return;
    const starred = req.body?.starred;
    if (typeof starred !== "boolean") return res.status(400).json({ message: "starred must be a boolean" });
    const row = await store.setThumbnailStarred(ctx.accountId, thumbId, starred);
    if (!row) return res.status(404).json({ message: "Not found" });
    res.json(toThumbnailView(row, deps.now()));
  }));

  app.delete("/api/social/accounts/:id/thumbnails/:thumbId", deps.requireAuth, wrapAsync(async (req, res) => {
    const ctx = await accountGate(req, res);
    if (!ctx) return;
    if (!canManageSocial(req.user, ctx.accountId)) return forbidden(res);
    const thumbId = positiveIntParam(req, res, "thumbId");
    if (thumbId === null) return;
    const row = await store.deleteThumbnail(ctx.accountId, thumbId);
    if (!row) return res.status(404).json({ message: "Not found" });
    await removeQuietly(row.filePath);
    res.json({ ok: true });
  }));

  return { idle: async () => { while (jobs.size) await Promise.all([...jobs]); } };
}
